import type { ImgHTMLAttributes } from 'react'
import manifest from '@/data/image-manifest.json'

type ManifestEntry = {
  width: number
  height: number
  variants: { w: number; src: string }[]
  /** Optional art-directed portrait crop (see CROPS in optimize-images.mjs). */
  portrait?: { w: number; src: string }
}

const IMAGES = manifest as Record<string, ManifestEntry>

/**
 * Responsive WebP lookup for a `/images/*.jpg|png` path.
 * Variants are pre-generated by `npm run images:optimize`; unknown paths
 * fall back to the original file untouched.
 */
export function getResponsiveImage(src: string) {
  const entry = IMAGES[src]
  if (!entry) return { src }
  return {
    // Largest WebP variant as the default — every evergreen browser decodes WebP.
    src: entry.variants[entry.variants.length - 1].src,
    srcSet: entry.variants.map((v) => `${v.src} ${v.w}w`).join(', '),
  }
}

/** Art-directed portrait crop for phones, if one was generated for `src`. */
export function getPortraitImage(src: string) {
  return IMAGES[src]?.portrait ?? null
}

interface ResponsiveImgProps extends Omit<ImgHTMLAttributes<HTMLImageElement>, 'src' | 'srcSet'> {
  src: string
  /** Rendered width hint for the browser, e.g. `100vw` or `(max-width: 700px) 90vw, 400px`. */
  sizes: string
  /** Above-the-fold hero image: eager + high fetch priority. */
  priority?: boolean
}

/**
 * Drop-in `<img>` that serves the pre-generated WebP `srcSet` and lazy-loads
 * by default. Intrinsic width/height are deliberately not emitted: every call
 * site sizes its image through CSS (object-fit: cover inside a sized box), and
 * a height attribute would override rules that only set the width.
 * Server- and client-safe (no hooks), so it can be used in either.
 */
export function ResponsiveImg({
  src,
  sizes,
  priority = false,
  alt = '',
  ...rest
}: ResponsiveImgProps) {
  const image = getResponsiveImage(src)
  return (
    // eslint-disable-next-line @next/next/no-img-element
    <img
      {...image}
      sizes={image.srcSet ? sizes : undefined}
      alt={alt}
      loading={priority ? 'eager' : 'lazy'}
      decoding={priority ? 'sync' : 'async'}
      fetchPriority={priority ? 'high' : undefined}
      {...rest}
    />
  )
}
